# Conflict-serializability: build the precedence graph and look for a cycle
def graph(schedule):
    edges = set()
    for i, (t1, op1, x1) in enumerate(schedule):
        for t2, op2, x2 in schedule[i + 1:]:
            if t1 != t2 and x1 == x2 and "W" in (op1, op2):
                edges.add((t1, t2))   # earlier conflicting op -> later one
    return edges

def has_cycle(edges):
    nodes = {n for e in edges for n in e}
    def dfs(n, path):
        if n in path: return True
        return any(dfs(b, path | {n}) for a, b in edges if a == n)
    return any(dfs(n, set()) for n in nodes)

good = [("T1","R","A"),("T1","W","A"),("T2","R","A"),("T2","W","A")]
bad  = [("T1","R","A"),("T2","R","A"),("T1","W","A"),("T2","W","A")]
for name, s in (("serial-like", good), ("interleaved", bad)):
    e = graph(s)
    print(name, s)
    print("  edges:", sorted(e), "-> serializable:", not has_cycle(e))

# Wait-for graph: edge T -> U means T waits for a lock U holds
def find_cycle(waits):
    def dfs(node, path):
        if node in path:
            return path[path.index(node):]
        for nxt in waits.get(node, []):
            c = dfs(nxt, path + [node])
            if c: return c
        return None
    for n in waits:
        c = dfs(n, [])
        if c: return c
    return None

cost = {"T1": 500, "T2": 3, "T3": 40}      # rows changed so far
waits = {"T1": ["T2"], "T2": ["T3"], "T3": []}
print("waits:", waits, "-> cycle:", find_cycle(waits))
waits["T3"].append("T1")                    # T3 now waits for T1: deadlock
cyc = find_cycle(waits)
print("waits:", waits, "-> cycle:", cyc)
victim = min(cyc, key=lambda t: cost[t])    # cheapest to roll back
print("victim:", victim, "(cost", cost[victim], ")")
del waits[victim]
for v in waits.values():
    if victim in v: v.remove(victim)
print("after rollback:", waits, "-> cycle:", find_cycle(waits))
